std::vector<double> data = {...};
const size_t K = 100;

// 1. std::sort (Full Sort: IntroSort Hybrid)
// Complexity: O(N log N) worst-case (Heap fallback).
// Highly cache-optimized (QuickSort primary path).
std::sort(data.begin(), data.end());

// 2. std::partial_sort (Sort Top K)
// Implementation: Typically Max Heap (Heapsort variant).
// Complexity: O(N log K). Optimal when N >> K.
// V[0]...V[K-1] are sorted; V[K]...V[N-1] are unsorted >= V[K-1].
std::partial_sort(
    data.begin(), data.begin() + K, data.end());

// Note: IntroSort = QuickSort + HeapSort (worst-case detection) + InsertionSort (small arrays).
